#include <linux/sched.h>
#include <linux/cred.h>
#include <linux/key.h>
#include <linux/userns.h>
#include <linux/gfp.h>

int copy_creds_for_task(struct task_struct *p, unsigned long clone_flags)
{
    struct cred *new;
    int ret = 0;

    new = prepare_creds();
    if (!new)
        return -ENOMEM;

    if (clone_flags & CLONE_NEWUSER) {
        struct user_namespace *new_user_ns;

        new_user_ns = create_user_ns(new);
        if (IS_ERR(new_user_ns)) {
            ret = PTR_ERR(new_user_ns);
            goto error;
        }
        new->user_ns = new_user_ns;
    }

    if (clone_flags & CLONE_THREAD) {
        new->tty = NULL;
        new->utask = NULL;
        new->process_keyring = NULL;
        new->session_keyring = NULL;
    } else {
        key_put(new->session_keyring);
        new->session_keyring = NULL;
    }

    ret = security_task_fix_setuid(new, p->cred, clone_flags);
    if (ret)
        goto error;

    commit_creds(new);
    return 0;

error:
    abort_creds(new);
    return ret;
}

int copy_credentials(struct task_struct *p, unsigned long clone_flags)
{
    struct cred *new;

    new = prepare_creds();
    if (!new)
        return -ENOMEM;

    if (clone_flags & CLONE_NEWUSER) {
        /* Handle user namespace creation if needed */
        if (user_ns_create(new) < 0) {
            abort_creds(new);
            return -ENOMEM;
        }
    }

    if (clone_flags & CLONE_THREAD) {
        /* Thread keyrings should be shared among threads */
        new->thread_keyring = p->cred->thread_keyring;
        get_keyring(new->thread_keyring);
    } else {
        new->thread_keyring = NULL;
    }

    if (clone_flags & CLONE_CREDENTIALS) {
        /* Share credentials with parent if requested */
        get_cred(new);
    } else {
        /* Prepare new credentials */
        if (prepare_new_credentials(new) < 0) {
            abort_creds(new);
            return -ENOMEM;
        }
    }

    if (clone_flags & CLONE_SESSION_KEYRING) {
        new->session_keyring = p->cred->session_keyring;
        get_keyring(new->session_keyring);
    }

    if (set_creds(p, new) < 0) {
        abort_creds(new);
        return -ENOMEM;
    }

    return 0;
}

#include <linux/cred.h>
#include <linux/key.h>
#include <linux/slab.h>
#include <linux/errno.h>

int copy_credentials(struct task_struct *p, unsigned long clone_flags) {
    struct cred *new;
    int ret = 0;

    new = prepare_creds();
    if (!new)
        return -ENOMEM;

    if (clone_flags & CLONE_SHARE_CREDENTIALS) {
        put_cred(new);
        get_cred(p->cred);
        return 0;
    }

    new->user_ns = NULL;
    new->tgcred = NULL;
    new->sgcred = NULL;
    new->session_keyring = NULL;

    if (clone_flags & CLONE_NEWUSER) {
        new->user_ns = create_userns(p->cred->user_ns);
        if (IS_ERR(new->user_ns)) {
            ret = PTR_ERR(new->user_ns);
            goto error;
        }
    }

    if (p->cred->thread_keyring)
        key_get(p->cred->thread_keyring);

    if (p->cred->process_keyring)
        key_get(p->cred->process_keyring);

    if (p->cred->session_keyring)
        key_get(p->cred->session_keyring);

    set_cred(new);

    return 0;

error:
    abort_creds(new);
    return ret;
}

int copy_creds(struct task_struct *p, unsigned long clone_flags)
{
    int ret;

    p->cred = get_current_cred();
    if (!p->cred)
        return -ENOMEM;

    if (clone_flags & CLONE_THREAD) {
        p->cred->thread_keyring = NULL;
        if (current->cred->thread_keyring)
            p->cred->thread_keyring = key_get(
                current->cred->thread_keyring);
    }

    if (clone_flags & CLONE_NEWUSER) {
        struct user_namespace *new_user_ns;

        new_user_ns = create_user_ns(p->cred);
        if (IS_ERR(new_user_ns))
            return PTR_ERR(new_user_ns);

        p->cred->user_ns = new_user_ns;
    }

    if (clone_flags & CLONE_NEWSESSION) {
        p->cred->session_keyring = NULL;
        if (current->cred->session_keyring)
            p->cred->session_keyring = key_get(
                current->cred->session_keyring);
    }

    return 0;
}

#include <linux/sched.h>
#include <linux/cred.h>
#include <linux/key.h>
#include <linux/namespace.h>

int copy_credentials(struct task_struct *p, unsigned long clone_flags)
{
    struct cred *new;
    int ret = 0;

    new = prepare_creds();
    if (!new)
        return -ENOMEM;

    if (clone_flags & CLONE_NEWUSER) {
        struct user_namespace *ns;
        ns = create_user_namespace(current_cred());
        if (IS_ERR(ns)) {
            ret = PTR_ERR(ns);
            goto error;
        }
        new->user_ns = ns;
    }

    if (clone_flags & CLONE_THREAD) {
        new->thread_keyring = NULL;
    } else {
        if (p->cred->thread_keyring) {
            new->thread_keyring = key_get(p->cred->thread_keyring);
        }
    }

    if (clone_flags & CLONE_NEWSESSION) {
        new->session_keyring = NULL;
    } else {
        if (p->cred->session_keyring) {
            new->session_keyring = key_get(p->cred->session_keyring);
        }
    }

    ret = security_task_fix_setuid(new, p->cred, clone_flags);
    if (ret)
        goto error;

    commit_creds(new);
    return 0;

error:
    abort_creds(new);
    return ret;
}
